using System;using System.IO;using System.Collections.Generic;using ScoreModern.RecoveredFragments;
class InputAutomaticBeamsProof {
 static int Main(string[] a){try{byte[] ds=File.ReadAllBytes(a[0]),before=File.ReadAllBytes(a[1]),tokens=File.ReadAllBytes(a[2]),prefs=File.ReadAllBytes(a[3]),after=File.ReadAllBytes(a[4]),afterTokens=File.ReadAllBytes(a[5]),ads=File.ReadAllBytes(a[6]);int count=BitConverter.ToInt16(ds,0x8798),notes=BitConverter.ToInt16(ds,0x8792);var rows=new List<float[]>();for(int i=0;i<count;i++){var row=new float[15];Buffer.BlockCopy(before,i*60,row,0,60);rows.Add(row);}float[] pairs=InputAutomaticBeams.Groups(rows,InputAutomaticBeams.Durations(rows),BitConverter.ToSingle(tokens,6),(short)BitConverter.ToSingle(tokens,10));if(pairs.Length!=BitConverter.ToInt16(afterTokens,0))throw new Exception("Automatic endpoint count");for(int i=0;i<pairs.Length;i++)if(pairs[i]!=BitConverter.ToSingle(afterTokens,2+i*4))throw new Exception("Endpoint "+i);int[] map=new int[notes],stems=new int[notes];for(int i=1;i<notes;i++){map[i]=BitConverter.ToInt16(before,0x2b5a+i*2);stems[i]=BitConverter.ToInt16(before,0x2a2e+i*2);}for(int i=0;i<pairs.Length;i+=2){var result=InputUniformBeam.Build(rows,map,stems,pairs[i],pairs[i+1],0,200,BitConverter.ToSingle(prefs,0));rows=result.Records;stems=result.ForcedStems;}if(rows.Count!=BitConverter.ToInt16(ads,0x8798))throw new Exception("Record count");for(int i=0;i<rows.Count;i++)for(int p=0;p<15;p++)if(BitConverter.ToInt32(BitConverter.GetBytes(rows[i][p]),0)!=BitConverter.ToInt32(after,i*60+p*4))throw new Exception("Record "+i+" P"+(p+1)+": "+rows[i][p]+" != "+BitConverter.ToSingle(after,i*60+p*4));Console.WriteLine("PASS "+pairs.Length+" original automatic endpoints and "+rows.Count*15+" beam construction words");return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
